/** Measure Bun's server RSS while uploading generated bytes; no input file is created. */
import { createHash } from 'node:crypto';
import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { createFileLfsStore } from '../src/bun/lfs-store.js';
import { serveRepository } from '../src/bun/serve.js';
import { openBunSqlite } from '../src/bun/sqlite.js';
import { createMemoryGitStore } from '../src/server/memory-git.js';
import { createServer } from '../src/server/server.js';
import { LfsStoreError, type LfsStore } from '../src/server/lfs-store.js';
import { Ok } from 'wellcrafted/result';

type Mode = 'null' | 'file';
const mode = Bun.argv[2] as Mode | '--server';
const chunk = new Uint8Array(64 * 1024);
const sizeOf = (selected: Mode) =>
	selected === 'null' ? 1024 ** 3 : 256 * 1024 ** 2;

function nullStore(): LfsStore {
	return {
		async has() {
			return false;
		},
		async get() {
			return null;
		},
		async put(oid, size, body) {
			const digest = createHash('sha256');
			let count = 0;
			try {
				const reader = body.getReader();
				for (
					let read = await reader.read();
					!read.done;
					read = await reader.read()
				) {
					count += read.value.byteLength;
					digest.update(read.value);
				}
			} catch (cause) {
				return LfsStoreError.Failed({ cause });
			}
			return count === size && digest.digest('hex') === oid
				? Ok('stored')
				: LfsStoreError.Mismatch();
		},
	};
}

if (mode === '--server') {
	const selected = Bun.argv[3] as Mode;
	const dir = Bun.argv[4]!;
	const server = createServer({
		store: openBunSqlite(),
		git: createMemoryGitStore(),
	});
	const served = serveRepository({
		repository: 'bench',
		serverId: 'bench',
		server,
		lfs:
			selected === 'null'
				? nullStore()
				: createFileLfsStore(join(dir, 'blobs')),
		authenticate: () => ({ user: 'bench', role: 'owner' }),
	});
	process.stdout.write(`${served.url}\n`);
} else if (mode === 'null' || mode === 'file') {
	const dir = await mkdtemp(join(import.meta.dir, '.bench-lfs-'));
	const child = Bun.spawn({
		cmd: [process.execPath, import.meta.path, '--server', mode, dir],
		stdout: 'pipe',
		stderr: 'inherit',
	});
	try {
		const reader = child.stdout.getReader();
		let line = '';
		while (!line.includes('\n')) {
			const next = await reader.read();
			if (next.done) throw new Error('Server did not start');
			line += new TextDecoder().decode(next.value);
		}
		const url = line.slice(0, line.indexOf('\n'));
		const size = sizeOf(mode);
		const repeats = size / chunk.byteLength;
		const digest = createHash('sha256');
		for (let index = 0; index < repeats; index++) digest.update(chunk);
		const oid = digest.digest('hex');
		const rss = () => {
			const result = Bun.spawnSync([
				'ps',
				'-o',
				'rss=',
				'-p',
				String(child.pid),
			]);
			return Number(new TextDecoder().decode(result.stdout).trim()) * 1024;
		};
		const baseline = rss();
		let peak = baseline;
		const sampler = setInterval(() => {
			peak = Math.max(peak, rss());
		}, 100);
		let sent = 0;
		const body = new ReadableStream<Uint8Array>(
			{
				pull(controller) {
					if (sent === size) return controller.close();
					controller.enqueue(chunk);
					sent += chunk.byteLength;
				},
			},
			{ highWaterMark: 1 },
		);
		try {
			const response = await fetch(new URL(`lfs/objects/${oid}`, url), {
				method: 'PUT',
				headers: { 'content-length': String(size) },
				body,
				duplex: 'half',
			} as RequestInit);
			if (response.status !== 200)
				throw new Error(
					`PUT answered ${response.status}: ${await response.text()}`,
				);
			peak = Math.max(peak, rss());
		} finally {
			clearInterval(sampler);
		}
		process.stdout.write(
			JSON.stringify({
				mode,
				bytes: size,
				baselineMiB: +(baseline / 1024 ** 2).toFixed(1),
				peakMiB: +(peak / 1024 ** 2).toFixed(1),
				growthMiB: +((peak - baseline) / 1024 ** 2).toFixed(1),
			}) + '\n',
		);
	} finally {
		child.kill();
		await child.exited;
		await rm(dir, { recursive: true, force: true });
	}
} else {
	throw new Error('Usage: bun scripts/bench-lfs-put.ts null|file');
}
